<?php defined('PREVENT_DIRECT_ACCESS') OR exit('No direct script access allowed');
$max = max(1, ...array_values(array_map(fn($d) => $d['hourly'] + $d['overnight'], $byDay))); $n = max(1, count($byDay)); $bw = 560 / $n; $sum = max(1, array_sum($byStay));
$hm = max(1, ...array_values($heat ?: [1])); ?>
<div class="row between"><h1>Reports</h1><a class="btn btn-out" href="<?= e(site_url('admin/reports/export')) ?>?from=<?= e($from) ?>&amp;to=<?= e($to) ?>">Export CSV</a></div>
<form method="get" action="<?= e(site_url('admin/reports')) ?>" class="row" style="margin:12px 0"><input type="date" name="from" value="<?= e($from) ?>" style="max-width:190px" aria-label="From"><input type="date" name="to" value="<?= e($to) ?>" style="max-width:190px" aria-label="To"><button class="btn btn-ink" type="submit">Show</button></form>
<div class="grid g4"><div class="stat dark"><div class="l">Total revenue</div><div class="v"><?= e(money($total)) ?></div></div><div class="stat"><div class="l">Paid bookings</div><div class="v"><?= (int) $count ?></div></div><div class="stat"><div class="l">Avg. hourly stay</div><div class="v"><?= e($avgHours) ?> hrs</div></div><div class="stat"><div class="l">Avg. per booking</div><div class="v"><?= e(money($count ? $total / $count : 0)) ?></div></div></div>
<div class="grid" style="grid-template-columns:1.6fr 1fr;margin-top:20px;align-items:start"><div class="card"><div class="row between"><h3>Revenue by day</h3><span class="small mute legend"><i style="background:#0E7C86"></i>Hourly<i style="background:#0B2233"></i>Overnight</span></div>
<svg class="bars" viewBox="0 0 600 240" role="img" aria-label="Revenue by day"><?php $i = 0; foreach ($byDay as $d => $r): $hh = 180 * $r['hourly'] / $max; $oh = 180 * $r['overnight'] / $max; $x = 20 + $i * $bw; ?>
<rect x="<?= round($x + 4, 1) ?>" y="<?= round(200 - $hh, 1) ?>" width="<?= round($bw - 8, 1) ?>" height="<?= round($hh, 1) ?>" fill="#0E7C86"/><rect x="<?= round($x + 4, 1) ?>" y="<?= round(200 - $hh - $oh, 1) ?>" width="<?= round($bw - 8, 1) ?>" height="<?= round($oh, 1) ?>" fill="#0B2233"/>
<text x="<?= round($x + $bw / 2, 1) ?>" y="220" text-anchor="middle" font-size="11" fill="#4F6574"><?= e(date($n > 10 ? 'j' : 'D', strtotime($d))) ?></text><?php $i++; endforeach; ?><line x1="14" y1="200" x2="590" y2="200" stroke="#DCE6EB"/></svg></div>
<div class="card"><h3>Hourly vs overnight</h3><?php foreach ($byStay as $k => $amt): ?><div class="row between small"><span><?= e(ucfirst($k)) ?></span><b><?= e(money($amt)) ?></b></div><progress class="meter" max="100" value="<?= (int) round($amt / $sum * 100) ?>"></progress><div style="height:12px"></div><?php endforeach; ?>
<h4 style="margin-top:12px">By room type</h4><?php foreach ($byType as $k => $amt): ?><div class="row between small"><span><?= e($k) ?></span><b><?= e(money($amt)) ?></b></div><?php endforeach; ?><?php if (!$byType): ?><p class="mute small">No paid bookings in this range.</p><?php endif; ?></div></div>
<div class="card" style="margin-top:20px"><div class="row between"><h3>Peak hours (check-ins by weekday and hour)</h3><span class="small mute">Darker = busier</span></div>
<div class="heat"><span></span><?php for ($h = 8; $h <= 21; $h++): ?><em class="small mute" style="font-style:normal"><?= $h > 12 ? $h - 12 : $h ?><?= $h >= 12 ? 'p' : 'a' ?></em><?php endfor; ?>
<?php foreach (['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as $di => $dn): ?><em class="small mute" style="font-style:normal"><?= e($dn) ?></em><?php for ($h = 8; $h <= 21; $h++): $c = $heat[$di . '-' . $h] ?? 0; $lv = $c ? min(4, 1 + (int) floor(3 * $c / $hm)) : 0; ?><span class="h<?= $lv ?>" title="<?= (int) $c ?> check-ins"></span><?php endfor; ?><?php endforeach; ?></div></div>
